17	import { cli } from 'cleye';
18	import type { CliCommandContext } from '@backstage/cli-node';
19	import { ActionsClient } from '../lib/ActionsClient';
20	import { schemaToFlags } from '../lib/schemaToFlags';
21	import { resolveAuth } from '../lib/resolveAuth';
22	
23	export default async ({ args, info }: CliCommandContext) => {
24	  const instanceIdx = args.indexOf('--instance');
25	  const instanceFlag = instanceIdx !== -1 ? args[instanceIdx + 1] : undefined;
26	
27	  // Skip flag names, flag values (the argument after a known flag), and
28	  // the --instance value position so we only pick up positional arguments.
29	  const skipIndices = new Set<number>();
30	  if (instanceIdx !== -1) {
31	    skipIndices.add(instanceIdx);
32	    skipIndices.add(instanceIdx + 1);
33	  }
34	
35	  let actionId: string | undefined;
36	  let actionIdIdx = -1;
37	  for (let i = 0; i < args.length; i++) {
38	    if (!skipIndices.has(i) && !args[i].startsWith('-')) {
39	      actionId = args[i];
40	      actionIdIdx = i;
41	      break;
42	    }
43	  }
44	
45	  const wantsHelp = args.includes('--help') || args.includes('-h');
46	
47	  if (wantsHelp && actionId) {
48	    let actionSchemaFlags: Record<string, unknown> = {};
49	    try {
50	      const { accessToken, baseUrl } = await resolveAuth(instanceFlag);
51	      const client = new ActionsClient(baseUrl, accessToken);
52	      const actions = await client.listForPlugin(actionId);
53	      const action = actions.find(a => a.id === actionId);
54	      if (action) {
55	        actionSchemaFlags = schemaToFlags(action.schema.input as any);
56	      }
57	    } catch {
58	      process.stderr.write(
59	        'Unable to retrieve action schema. Showing generic help.\n',
60	      );
61	    }
62	
63	    cli(
64	      {
65	        help: info,
66	        parameters: ['<action-id>'],
67	        flags: {
68	          instance: {
69	            type: String,
70	            description: 'Name of the instance to use',
71	          },
72	          ...actionSchemaFlags,
73	        },
74	      },
75	      undefined,
76	      args,
77	    );
78	    return;
79	  }
80	
81	  if (wantsHelp || !actionId) {
82	    cli(
83	      {
84	        help: info,
85	        parameters: ['<action-id>'],
86	        flags: {
87	          instance: {
88	            type: String,
89	            description: 'Name of the instance to use',
90	          },
91	        },
92	      },
93	      undefined,
94	      wantsHelp ? args : ['--help', ...args],
95	    );
96	    return;
97	  }
98	
99	  const { accessToken, baseUrl } = await resolveAuth(instanceFlag);
100	
101	  const client = new ActionsClient(baseUrl, accessToken);
102	  const actions = await client.listForPlugin(actionId);
103	  const action = actions.find(a => a.id === actionId);
104	
105	  if (!action) {
106	    throw new Error(
107	      `Action "${actionId}" not found. Run "actions list" to see available actions.`,
108	    );
109	  }
110	
111	  const schemaFlags = schemaToFlags(action.schema.input as any);
112	
113	  const flagArgs = args.filter((_, i) => i !== actionIdIdx);
114	
115	  const { flags } = cli(
116	    {
117	      help: info,
118	      flags: {
119	        instance: {
120	          type: String,
121	          description: 'Name of the instance to use',
122	        },
123	        ...schemaFlags,
124	      },
125	    },
126	    undefined,
127	    flagArgs,
128	  );
129	
130	  const allFlags = flags as Record<string, unknown>;
131	  const input: Record<string, unknown> = {};
132	  for (const [key, value] of Object.entries(allFlags)) {
133	    if (key !== 'instance' && value !== undefined) {
134	      input[key] = value;
135	    }
136	  }
137	
138	  const output = await client.execute(actionId, input);
139	  process.stdout.write(`${JSON.stringify(output, null, 2)}\n`);
140	};
